const navItems=[['start','info','Από πού ξεκινώ;','Start here'],['compare','chart','Σύγκριση σεναρίων','Compare scenarios'],['overview','grid','Εικόνα','Overview'],['budget','wallet','Το πλάνο','Budget'],['actual','list','Πραγματικές κινήσεις','Actuals'],['subscriptions','repeat','Συνδρομές','Subscriptions'],['goals','target','Στόχοι & ασφάλεια','Goals & reserve'],['projection','chart','Προβολές','Projections'],['household','users','Νοικοκυριό','Household'],['files','file','Αρχεία & οδηγός','Files & guide']];
function currentTitle(){const v=navItems.find(v=>v[0]===view);return L(v[2],v[3]);}
