 workspace=S.sync(workspace,state);
 if(workingShared||booting)return true;
 try{const payload=JSON.stringify(S.clean(workspace));localStorage.setItem(WORKSPACE_STORE,payload);localWorkspaceSnapshot=S.clean(workspace);localSnapshot=E.clone(state);storageIssue=false;status();return true;}
