$('demoBanner').hidden=!state.isDemo;if(state.isDemo)$('demoBanner').innerHTML=`<span>${L('ΠΑΡΑΔΕΙΓΜΑ · Όλα τα ποσά και τα άτομα είναι φανταστικά.','EXAMPLE · All amounts and people are fictional.')}</span><div class="banner-actions"><button class="plain" data-action="newBlank">${L('Ξεκίνα με τα δικά σου','Start your own')}</button></div>`;
